#include "../Source/PluginProcessor.h"
#include "../Source/PluginEditor.h"
#include "../Source/StudioRack.h"
#include <iostream>
#include <stdexcept>
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void set(SpaceInfinityProcessor& p,const juce::String& id,float value){auto* a=p.state.getParameter(id);check(a!=nullptr,id.toRawUTF8());a->setValueNotifyingHost(a->convertTo0to1(value));}
void clean(SpaceInfinityProcessor& p){p.loadPreset(0);for(auto id:{"compEnabled","delayEnabled","reverbEnabled","chorusEnabled","flangerEnabled","phaserEnabled","gateEnabled","pumpEnabled","eqEnabled","convolverEnabled","osc2Enabled"})set(p,id,0);set(p,"osc1PhaseReset",1);set(p,"osc2PhaseReset",1);set(p,"wave",2);set(p,"mix",0);set(p,"gain",.2f);set(p,"cutoff",16000);set(p,"res",0);set(p,"drive",0);set(p,"attack",.001f);set(p,"ampSustain",1);set(p,"noiseLevel",0);set(p,"lfodepth",0);}
double energy(SpaceInfinityProcessor& p,int blocks=70){p.prepareToPlay(48000,256);juce::AudioBuffer<float> audio(2,256);double sum=0;for(int b=0;b<blocks;++b){juce::MidiBuffer midi;if(b==0)midi.addEvent(juce::MidiMessage::noteOn(1,60,.8f),0);p.processBlock(audio,midi);for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i){const auto v=audio.getSample(ch,i);check(std::isfinite(v),"finite workflow audio");if(b>blocks/2)sum+=v*v;}}return sum;}
juce::Component* named(juce::Component& c,const juce::String& name){if(c.getName()==name)return &c;for(auto* child:c.getChildren())if(auto* found=named(*child,name))return found;return nullptr;}
double eqEnergy(const std::array<float,9>& settings,float hz){studio::WetEQ eq;eq.prepare(48000);eq.configure(settings);double sum=0;for(int i=0;i<24000;++i){float v=.1f*std::sin(juce::MathConstants<float>::twoPi*hz*i/48000);auto out=eq.process(v,-v);check(std::isfinite(out[0]),"wet EQ stability");check(std::abs(out[0]+out[1])<.00001f,"wet EQ stereo independence");if(i>12000)sum+=out[0]*out[0];}return sum;}
}
int runWorkflowSmoke(){try{
    std::array<float,9> flat{200,0,.707f,1500,0,1,6000,0,.707f};
    studio::WetEQ bypass;bypass.prepare(48000);bypass.configure(flat);for(int i=0;i<500;++i){const float v=std::sin(float(i));const auto out=bypass.process(v,-v);check(out[0]==v&&out[1]==-v,"flat wet EQ exact bypass");}
    auto low=flat;low[1]=12;auto mid=flat;mid[4]=-12;auto high=flat;high[7]=12;
    check(eqEnergy(low,50)>eqEnergy(flat,50)*8,"wet low shelf boosts bass");check(eqEnergy(mid,1500)<eqEnergy(flat,1500)*.15,"wet mid bell cuts mids");check(eqEnergy(high,14000)>eqEnergy(flat,14000)*8,"wet high shelf boosts treble");
    studio::SmoothFlanger flange;flange.prepare(48000);flange.configure(.1f,1,10,.95f,180,1);double tail=0;for(int i=0;i<144000;++i){if(i==48000)flange.configure(10,0,.1f,-.95f,0,.8f);auto out=flange.process(i==0?1:0,0);for(auto v:out){check(std::isfinite(v)&&std::abs(v)<=2,"flanger extreme feedback stability");if(i>120000)tail+=v*v;}}check(tail<1,"flanger feedback decays");
    auto p=std::make_unique<SpaceInfinityProcessor>();clean(*p);const auto base=energy(*p);set(*p,"osc1Gain",-6);check(std::abs(energy(*p)/base-.2512)<.035,"oscillator A gain is independent dB gain");
    clean(*p);set(*p,"osc1Enabled",0);set(*p,"osc2Enabled",1);set(*p,"mix",1);const auto b=energy(*p);set(*p,"osc1Gain",-40);check(std::abs(energy(*p)/b-1)<.002,"A gain does not attenuate oscillator B");set(*p,"osc2Gain",-6);check(std::abs(energy(*p)/b-.2512)<.035,"oscillator B gain works");
    clean(*p);set(*p,"osc1Unison",7);set(*p,"osc1Detune",.1f);const auto narrow=energy(*p);set(*p,"osc2Detune",.9f);check(std::abs(energy(*p)/narrow-1)<.0001,"oscillator B detune leaves A untouched");set(*p,"osc1Detune",.9f);check(std::abs(energy(*p)/narrow-1)>.01,"oscillator A detune changes its unison sound");
    // An inaudible wet return must leave the dry signal untouched by its EQ.
    clean(*p);set(*p,"delayEnabled",1);set(*p,"echoMode",1);set(*p,"echoMix",0);set(*p,"delay",0);const auto dry=energy(*p);set(*p,"delayWetLowGain",18);set(*p,"delayWetMidGain",-18);set(*p,"delayWetHighGain",18);check(std::abs(energy(*p)/dry-1)<.0001,"delay EQ leaves dry audio unchanged");
    clean(*p);set(*p,"reverb",0);const auto reverbDry=energy(*p);set(*p,"reverbWetLowGain",18);set(*p,"reverbWetMidGain",-18);set(*p,"reverbWetHighGain",18);check(std::abs(energy(*p)/reverbDry-1)<.0001,"reverb EQ leaves dry audio unchanged");
    clean(*p);set(*p,"chorusEnabled",1);set(*p,"chorus",0);const auto stage=energy(*p);set(*p,"fxOutput4",6);check(std::abs(energy(*p)/stage-3.981)<.1,"FX output gain in dB");check(p->effectPeak(4)>0,"FX peak is published");set(*p,"gain",1);set(*p,"osc1Gain",6);set(*p,"fxOutput4",12);set(*p,"noiseLevel",1);set(*p,"subLevel",1);energy(*p);check(p->effectClipping(4),"FX clipping latch");check(!p->effectClipping(4),"clip flag consumed once");
    // A low-pass can be bypassed separately by A, B, sub and noise.
    clean(*p);set(*p,"wave",0);set(*p,"cutoff",80);set(*p,"filterMode",4);const auto filteredA=energy(*p);set(*p,"routeA",0);check(energy(*p)>filteredA*4,"oscillator A filter routing");
    clean(*p);set(*p,"osc1Enabled",0);set(*p,"osc2Enabled",1);set(*p,"mix",1);set(*p,"osc2Wave",0);set(*p,"cutoff",80);set(*p,"filterMode",4);const auto filteredB=energy(*p);set(*p,"routeB",0);check(energy(*p)>filteredB*4,"oscillator B filter routing");
    clean(*p);set(*p,"osc1Enabled",0);set(*p,"subLevel",.5f);set(*p,"subWave",2);set(*p,"cutoff",30);set(*p,"filterMode",4);set(*p,"routeSub",1);const auto filteredSub=energy(*p);set(*p,"routeSub",0);check(energy(*p)>filteredSub*4,"sub filter routing");for(int wave=0;wave<6;++wave){set(*p,"subWave",float(wave));check(energy(*p)>0,"all sub waveforms sound");}set(*p,"subEnabled",0);check(energy(*p)<.000001,"sub power switch");
    clean(*p);set(*p,"osc1Enabled",0);set(*p,"noiseLevel",.5f);set(*p,"cutoff",60);set(*p,"filterMode",4);const auto filteredNoise=energy(*p);set(*p,"routeNoise",0);check(energy(*p)>filteredNoise*4,"noise filter routing");
    clean(*p);set(*p,"osc1Unison",7);set(*p,"osc1Detune",.37f);set(*p,"osc2Detune",.12f);set(*p,"flangerMode",1);set(*p,"delayWetMidGain",-4);set(*p,"reverbWetHighGain",3);set(*p,"fxOutput1",-3);check(p->dropModulation("INFINITY:MACRO:0","flangerRate"),"blank macro can target FX");check(p->dropModulation("INFINITY:LFO:0","osc1Gain"),"LFO can target oscillator gain");
    juce::MemoryBlock saved;p->getStateInformation(saved);auto restored=std::make_unique<SpaceInfinityProcessor>();restored->setStateInformation(saved.getData(),int(saved.getSize()));for(auto id:{"osc1Detune","osc2Detune","flangerMode","delayWetMidGain","reverbWetHighGain","fxOutput1"})check(std::abs(p->state.getRawParameterValue(id)->load()-restored->state.getRawParameterValue(id)->load())<.00001,"workflow preset recall");check(restored->flexibleSourceTarget(0,0)==p->flexibleSourceTarget(0,0),"macro route recall");check(restored->flexibleSourceTarget(3,0)==p->flexibleSourceTarget(3,0),"LFO route recall");
    auto editor=std::unique_ptr<juce::AudioProcessorEditor>(p->createEditor());editor->setSize(1180,820);check(named(*editor,"Amp ATTACK")&&named(*editor,"Filter ATTACK"),"both envelopes on main page");check(named(*editor,"Sub oscillator")&&named(*editor,"Sub oscillator")->isVisible(),"sub on main page");check(named(*editor,"Oscillator 1 gain")&&named(*editor,"Oscillator 2 gain"),"both oscillator gains on main page");auto* attack=dynamic_cast<juce::Slider*>(named(*editor,"Amp ATTACK"));check(attack&&std::abs(attack->getValueFromText("0.25 ms")-.00025)<.00001,"fine attack millisecond entry");check(attack->getNormalisableRange().convertTo0to1(.01)>.2,"fine short-time knob travel");
    // Old sessions omit all new IDs and must retain the legacy algorithms.
    auto old=p->state.copyState();for(int i=old.getNumChildren();--i>=0;){const auto id=old.getChild(i).getProperty("id").toString();if(id=="modernUnison"||id=="flangerMode"||id.startsWith("osc1Gain")||id.startsWith("osc2Gain")||id.startsWith("delayWet")||id.startsWith("reverbWet")||id.startsWith("fxOutput"))old.removeChild(i,nullptr);}juce::MemoryBlock oldData;juce::AudioProcessor::copyXmlToBinary(*old.createXml(),oldData);restored->setStateInformation(oldData.getData(),int(oldData.getSize()));check(restored->state.getRawParameterValue("modernUnison")->load()==0&&restored->state.getRawParameterValue("flangerMode")->load()==0,"legacy algorithm compatibility");
    std::cout<<"Workflow: wet EQ response/dry isolation, flanger stability, oscillator gains, routing, sub, FX gain/meter/clipping, fine time entry and state compatibility passed\n";return 0;
}catch(const std::exception& e){std::cerr<<"Workflow failure: "<<e.what()<<'\n';return 120;}}
